import {MOSFET_LOSS_GROUPS,lossGroupState} from './loss-models.js';
import {QUANTITIES,characteristicName} from './characteristics.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const n=v=>Number.isFinite(v)?Number(v.toPrecision(6)).toString():'—';
const title=c=>c.sourceId?characteristicName(c.sourceId):`${QUANTITIES[c.yName]?.[0]||c.yName} vs ${QUANTITIES[c.xName]?.[0]||c.xName}`;
export function lossModelEditor(candidate,key,plot){const states=Object.fromEntries(Object.keys(MOSFET_LOSS_GROUPS).map(k=>[k,lossGroupState(candidate,k)])),s=states[key]||states.channel,g=s.group,active=s.active,rds=active&&[active.xName,active.yName].includes('Rds'),qrr=active&&[active.xName,active.yName].includes('Qrr'),statusClass=status=>status==='Ready'?'ready':status==='Needs review'?'review':status==='Missing curve'?'missing':'';let formula=rds&&key==='channel'?'p(t) = Rds(on) × Id²':qrr?'Err ≈ Qrr × blocking Vds; Prr = Σ Err / window duration':g.formula;const allReferences=active?[...new Set(active.iterations.flatMap(it=>Object.keys(it.deps||{})))]:[];
return `<div class="loss-model-context"><div><strong>${esc(candidate.part||'Unnamed alternative')}</strong><span>MOSFET · loss models & characteristics</span></div><div>${candidate.thermal.mode==='fixed'?'Tj':'Reference temperature'}: <b>${n(candidate.thermal.temperature)}°C</b> · ${candidate.gateType==='logic'?'Gate-on Vgs: '+n(candidate.vgsOn)+' V':'Analog gate waveform'}</div></div><div class="loss-model-layout"><div class="loss-model-groups" role="group" aria-label="MOSFET loss groups">${Object.entries(states).map(([id,state])=>`<button class="loss-model-group ${id===key?'selected':''}" data-loss-group="${id}" aria-pressed="${id===key}"><span><strong>${state.group.title}</strong><small>${state.group.hint}</small></span><span class="loss-model-status ${statusClass(state.status)}">${state.status}</span></button>`).join('')}</div><section class="loss-model-detail"><div class="panel-head"><h3>${g.title}</h3><span class="loss-model-status ${statusClass(s.status)}">${s.status}</span></div><label class="check"><input type="checkbox" id="lossModelEnabled" ${s.enabled?'checked':''}>${key==='temperature'?'Use temperature correction when an Rds model is active':'Include this loss contribution'}</label>${s.curves.length?`<label>Active characteristic<select id="lossModelChoice">${!active?'<option value="">Choose an active curve…</option>':''}${s.curves.map(c=>`<option value="${esc(c.id)}" ${c.id===active?.id?'selected':''}>${esc(title(c))} · ${c.iterations.length} iterations</option>`).join('')}</select></label>`:'<div class="empty">No characteristic added for this loss model.</div>'}${active?`<p class="caption">${allReferences.map(k=>{const values=active.iterations.map(it=>it.deps?.[k]).filter(Number.isFinite);return esc(QUANTITIES[k]?.[0]||k)+': '+(values.length?[...new Set(values)].sort((a,b)=>a-b).map(n).join(', '):'missing')+' '+esc(QUANTITIES[k]?.[1]||'');}).join(' · ')}</p>${plot(active)}`:''}<div class="loss-model-how"><strong>How it is used</strong><p>${g.use}</p><code>${esc(formula)}</code></div>${!s.enabled&&key!=='temperature'?'<p class="caption">Disabled: this contribution is excluded from losses and efficiency.</p>':''}${s.issues.map(message=>`<div class="notice warn">${esc(message)}</div>`).join('')}${key==='temperature'&&!s.applied?'<div class="notice">Correction is not currently applied. It requires enabled channel conduction using an Rds characteristic.</div>':''}${active&&s.curves.length>1?`<div class="notice warn">Active: ${esc(title(active))}. ${s.curves.filter(c=>c.id!==active.id).map(c=>esc(title(c))).join('; ')} — stored but not used for this loss.</div>`:''}${['on','off'].includes(key)&&active?`<label class="check"><input id="lossModelScale" type="checkbox" ${active.voltageScaling?'checked':''}>Scale switching energy linearly with blocking voltage</label><label class="check"><input id="lossModelIndependent" type="checkbox" ${active.temperatureIndependent?'checked':''}>Treat switching energy as temperature-independent</label>`:''}${key==='recovery'?`<label class="check"><input id="lossModelRecoveryConfirmed" type="checkbox" ${candidate.recoveryConfirmed?'checked':''}>Recovery definition reviewed: not already included in Eon</label>`:''}<div class="toolbar"><button class="primary small" data-add-loss-curve="${key}">+ Add curve</button><button class="ghost small" data-digitise-loss-curve="${key}">Digitise curve ↗</button>${active?`<button class="ghost small" data-edit-curve="${esc(active.id)}" data-curve-group="${key}">Edit / inspect</button><button class="ghost small danger" data-delete-curve="${esc(active.id)}">Remove active curve</button>`:''}</div><p class="caption">Ready means reference data and configured dependencies pass basic checks. Current, blocking-voltage, slew-rate and full waveform coverage are checked during analysis. Keep enabled categories consistent across alternatives.</p></section></div><details class="loss-model-library"><summary>All stored characteristics (${candidate.curves.length})</summary>${candidate.curves.map(c=>`<div class="curve-card"><div><strong>${esc(title(c))}</strong><small>${c.iterations?.length||0} iterations</small></div><button class="ghost small" data-edit-curve="${esc(c.id)}">Edit / inspect</button></div>`).join('')}<div class="toolbar"><button class="ghost small" id="importCurves">Import MAT / JSON</button></div></details>`;}
